import { demo } from './demo.js';
import {buildReviewRecord,reviewContext} from './review-record.js';
import {createReviewStorage} from './review-storage.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
let recovery=null, noteEditor=null, noteDrafts={}, openMode='single',undoBusy=false,pendingImport=null,pendingWordExport=null,importTicket=0,modalGeneration=0,importBusy=false,wordExportBusy=false;
let session=clone(demo), review, config, selected, view='redline',panel='changes',filter='pending',sourceView='reviewed',undo=[],pdf=null,compiling=false,toastTimer,revision=0,autoCompileTimer,compileError=null;
const storeKey='folio.review.v1', historyKey='folio.history.v1';
const reviewStorage=createReviewStorage({getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)},{activeKey:storeKey,historyKey});
let storageConflictNotified=false;
function history(){return reviewStorage.readHistory();}
function archiveCurrent(){if(!review||recovery)return;try{reviewStorage.archive(session);}catch(e){if(e.code==='REVIEW_STORAGE_CONFLICT'){showStorageConflictStatus();throw e;}throw Error('Recent reviews could not be saved. Save this review file before opening another document.');}}
const changes=()=>review?.segments.filter(s=>s.type==='change')||[];
const pending=()=>changes().filter(s=>!session.decisions[s.id]).length;
const material=()=>review.segments.map(s=>s.type==='equal'?s.before:session.decisions[s.id]==='rejected'?s.before:s.after).join('');
async function api(route,payload,retry=true){const r=await fetch('/api/'+route,{method:'POST',headers:{'Content-Type':'application/json','X-Folio-Token':config.token},body:JSON.stringify(payload)});const data=await r.json();if(r.status===403&&retry){const current=await fetch('/api/config');if(current.ok){config=await current.json();return api(route,payload,false);}}if(!r.ok)throw Error(data.error||'The local workspace could not complete this action.');return data;}

function showStorageConflictStatus(){const status=$('#save-status');status.textContent='Saving paused · Keep this review';status.setAttribute('role','button');status.tabIndex=0;status.title='Another tab saved changes. Save this version before reloading.';$('#save-dot').style.background='#c84229';if(!storageConflictNotified){storageConflictNotified=true;toast('Another tab saved a review. Your work is still here; save a review file before reloading.');}}
function storageConflictModal(){modal('Keep this version','Another tab saved a review. This tab has paused automatic saving.',`<p class="hint">Your wording, decisions and comments are still in this tab. Save a review file to keep this version.</p><p class="hint">Reloading or closing this tab will discard its unsaved work. The other tab’s saved review has been left untouched.</p>`,`<button class="button" data-action="close-modal">Keep reviewing</button><button class="button primary" data-export="session">Save this review</button>`);}
function persist(){if(recovery){$('#save-status').textContent='Saved review needs recovery — export it first';return;}try{reviewStorage.save(session);$('#save-status').textContent='Saved in this browser';$('#save-dot').style.background='#28231f';}catch(e){if(e.code==='REVIEW_STORAGE_CONFLICT'){showStorageConflictStatus();return;}$('#save-status').textContent='Not saved — export a review file';$('#save-dot').style.background='#c84229';}}
function toast(text){if(reviewStorage.conflicted&&/^(Comment saved|Review note saved|Wording saved)/.test(text))text=text.replace(' saved',' kept in this tab')+' · Automatic saving paused';$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
function modal(title,subtitle,body,footer=''){modalGeneration++;pendingWordExport=null; $('#modal-content').innerHTML=`<div class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();}
function modalError(e){let el=$('#modal .error-message');if(!el){el=document.createElement('div');el.className='error-message';$('#modal .modal-body').append(el);}el.textContent=e.message||String(e);}
function download(data,name,type='text/plain;charset=utf-8'){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function stem(){return(session.title||'Document').replace(/[^\p{L}\p{N}._ -]/gu,'').trim().replace(/\s+/g,'_')||'Document';}
function invalidate(){revision++;compileError=null;clearTimeout(autoCompileTimer);if(pdf){URL.revokeObjectURL(pdf.url);pdf=null;}$('#compile-status').textContent='Check PDF';}
function enrich(){let count=0,heading='Document',sectionId='';let index=0;for(const s of review.segments){if(s.heading){count++;heading=s.heading;sectionId=s.id;}s.section=heading;s.sectionId=sectionId;s.sectionNo=count;if(s.type==='change')s.number=++index;}$('#section-count').textContent=count;}
async function loadSession(next,{archive=true}={}){
 if(archive)try{reviewStorage.assertCurrent();}catch(e){if(e.code==='REVIEW_STORAGE_CONFLICT')showStorageConflictStatus();throw e;}
 const context=reviewContext(next.context);
 const nextReview=await api('compare',{before:next.before,after:next.after});
 if(next.beforeHash&&next.beforeHash!==nextReview.beforeHash||next.afterHash&&next.afterHash!==nextReview.afterHash)throw Error('The source hashes do not match this review file. The current review has been preserved.');
 const ids=new Set(nextReview.segments.filter(s=>s.type==='change').map(s=>s.id));
 const noteIds=new Set(nextReview.segments.map(s=>s.id));
 for(const [id,value]of Object.entries(next.decisions||{}))if(!ids.has(id)||!['accepted','rejected'].includes(value))throw Error('This review contains a decision that does not match its source documents.');
 for(const [id,notes]of Object.entries(next.comments||{}))if(!noteIds.has(id)||!Array.isArray(notes)||notes.some(n=>typeof n.text!=='string'||typeof n.at!=='string'))throw Error('The notes in this review file could not be read.');
 if(next.authoring&&(typeof next.authoring.originalAfter!=='string'||new TextEncoder().encode(next.authoring.originalAfter).length>300000))throw Error('The preserved proposal in this review could not be read.');
 const attachments=next.attachments?.length?(await api('word/restore',{files:next.attachments})).files:[];
 if(archive)archiveCurrent();
 noteEditor=null;noteDrafts={};$('.app-shell').classList.remove('mobile-review-open');
 invalidate();session={context,workspaceId:next.workspaceId||crypto.randomUUID(),authoring:next.authoring||null,attachments,conversion:next.conversion||null,title:String(next.title||'Untitled document'),matter:String(next.matter||'Document comparison'),before:next.before,after:next.after,beforeName:String(next.beforeName||'Original.tex'),afterName:String(next.afterName||'Proposed.tex'),decisions:next.decisions||{},comments:next.comments||{},audit:Array.isArray(next.audit)?next.audit:[],demo:!!next.demo,beforeHash:nextReview.beforeHash,afterHash:nextReview.afterHash};review=nextReview;filter='pending';panel='changes';enrich();selected=changes().find(s=>!session.decisions[s.id])?.id||changes()[0]?.id;undo=[];persist();render();
}
function inline(s,short=false){if(s.sourceOnly)return `<span class="hint">Source or formatting changed; wording is unchanged.</span><br>${esc(renderedText(s))}`;let words=s.words;const oldText=renderedText(s,'before'),newText=renderedText(s);const changed=words.filter(w=>w.added||w.removed).reduce((n,w)=>n+w.value.length,0);if(oldText.length>80&&newText.length>80&&changed/(oldText.length+newText.length)>.55)return `<del class="replacement">${esc(oldText)}</del><ins class="replacement">${esc(newText)}</ins>`;if(short){let first=words.findIndex(w=>w.added||w.removed),last=words.findLastIndex(w=>w.added||w.removed);if(first>=0){words=words.slice(Math.max(0,first-1),last+2).map((w,i,arr)=>({...w,value:!w.added&&!w.removed&&i===0&&w.value.length>38?'…'+w.value.slice(-38):!w.added&&!w.removed&&i===arr.length-1&&w.value.length>48?w.value.slice(0,48)+'…':w.value}));}}
 return words.map(w=>w.added?`<ins>${esc(w.value)}</ins>`:w.removed?`<del>${esc(w.value)}</del>`:esc(w.value)).join('')||'<span class="hint">Source-level change. Open Source to inspect it.</span>';}
function renderedText(s,which='after'){return s.words.filter(w=>which==='before'?!w.added:!w.removed).map(w=>w.value).join('');}
function editable(s){return session.decisions[s.id]==='rejected'?s.editorBefore:s.editorAfter;}
function documentHtml(){let html='';for(const s of review.segments){
 if(s.preamble||s.end){if(s.type==='change')html+=`<div class="doc-paragraph change ${selected===s.id?'selected':''}" data-select="${s.id}" tabindex="0" role="button"><span class="hint">Document configuration changed. Review the exact source.</span><span class="change-marker">${s.number}</span></div>`;continue;}
 if(s.heading&&s.type==='equal'){html+=`<h3 class="document-section" id="${s.id}">${session.attachments.length?'':`<span class="clause-number">${s.sectionNo}.</span>`}${esc(s.heading)}</h3>`;continue;}
 const d=session.decisions[s.id];let text=s.type==='equal'?esc(renderedText(s)):view==='reading'?esc(renderedText(s,d==='rejected'?'before':'after')):d?esc(renderedText(s,d==='rejected'?'before':'after')):inline(s);
 if(!text.trim())continue;
 const editor=editable(s);
 const interactive=view!=='reading'&&(s.type==='change'||session.comments[s.id]?.length||editor?.editable);
 const extra=view!=='reading'&&(s.type==='change'||session.comments[s.id]?.length)?`change ${selected===s.id?'selected':''}`:'';
 html+=`<div id="${s.id}" class="doc-paragraph ${extra}" ${interactive?`data-select="${s.id}" tabindex="0" role="button" aria-label="${s.number?'Change '+s.number:session.comments[s.id]?.length?'Comment':'Passage'}, ${esc(s.section)}"`:''}>${text}${editor?.editable?`<button class="edit-affordance" data-edit="${s.id}" aria-label="Edit wording in ${esc(s.section)}">Edit wording</button>`:''}${view!=='reading'&&s.type==='change'?`<span class="change-marker">${d==='accepted'?'✓':d==='rejected'?'×':s.number}</span>`:''}${view!=='reading'&&s.type==='equal'&&session.comments[s.id]?.length?'<span class="change-marker" aria-label="Comment">✎</span>':''}${view!=='reading'&&d?`<span class="decision-indicator">${d==='accepted'?'ACCEPTED':'ORIGINAL RETAINED'}</span>`:''}</div>`;
 }return html;}
function renderOutline(){const headings=review.segments.filter(s=>s.heading);$('#outline-list').innerHTML=headings.map(s=>{const n=changes().filter(c=>c.sectionId===s.id&&!session.decisions[c.id]).length;const active=review.segments.find(c=>c.id===selected)?.sectionId===s.id;return`<button class="outline-item ${active?'selected':''}" data-jump="${s.id}"><span class="outline-number">${String(s.sectionNo).padStart(2,'0')}</span><span>${esc(s.heading)}</span>${n?`<span class="outline-count">${n}</span>`:''}</button>`;}).join('')||'<div class="empty-state">No section headings.<br>Changes are listed on the right.</div>';}
function filtered(){return changes().filter(s=>filter==='all'||filter==='pending'&&!session.decisions[s.id]||filter==='attention'&&s.signals.length&&!session.decisions[s.id]||session.decisions[s.id]===filter);}
function noteByline(n){return `${Number.isFinite(Date.parse(n.at))?new Date(n.at).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):'Date not supplied'} · ${n.origin==='word'?n.author||'Author not supplied':'Local reviewer'}${n.origin==='word'?' · From Word':''}`;}
function renderCards(){
 $('#change-total').textContent=changes().length;$('#note-total').textContent=Object.values(session.comments).reduce((sum,a)=>sum+a.length,0);
 $$('.inspector-tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.panel===panel));$('.filter-row').classList.toggle('hidden',panel==='notes');$('#change-filter').value=filter;
 const activeChange=changes().find(s=>s.id===selected);$('.inspector').classList.toggle('has-pending-selection',!!activeChange&&!session.decisions[selected]);$('#mobile-actions').innerHTML=activeChange&&!session.decisions[selected]?`<button class="accept-button" data-decide="accepted" data-id="${selected}">✓ Accept</button><button class="reject-button" data-decide="rejected" data-id="${selected}">Keep original</button>`:'';
 $('#review-step').textContent=activeChange?`Change ${activeChange.number} of ${changes().length}`:'Ready to review';
 const list=panel==='notes'?review.segments.filter(s=>session.comments[s.id]?.length||s.id===selected&&s.type==='equal'&&editable(s)?.editable):filtered();$('#filter-count').textContent=`${list.length} ${list.length===1?'change':'changes'}`;
 $('#change-list').innerHTML=list.map(s=>{let d=session.decisions[s.id],active=selected===s.id;return`<div class="change-card ${active?'selected':''}" data-card="${s.id}" tabindex="0" aria-label="${s.number?'Change '+s.number:'Comment'}: ${esc(s.section)}"><div class="card-meta"><span class="card-index"><span class="tiny-circle">${s.number||'✎'}</span> ${d?d==='accepted'?'Accepted':'Original kept':s.type==='change'?'Proposed change':session.comments[s.id]?.length?'Comment on unchanged wording':'Selected passage'}</span><span>Line ${s.oldLine}</span></div><h3 class="card-heading">${s.sectionNo&&!session.attachments.length?`${s.sectionNo}. `:''}${esc(s.section)}</h3><div class="card-diff">${inline(s,true)}</div>${active&&s.signals.length?`<div class="attention-tags">${s.signals.map(x=>`<span class="attention-tag">${esc(x.label)}</span>`).join('')}</div>`:''}${active&&s.signals.length?`<p class="attention-detail">${esc(s.signals[0].detail)}</p>`:''}${panel==='changes'&&s.type==='change'?d?`<div class="card-actions"><button class="reject-button" data-reopen="${s.id}">Reopen change</button></div>`:`<div class="card-actions"><button class="accept-button" data-decide="accepted" data-id="${s.id}"><span>✓</span> Accept</button><button class="reject-button" data-decide="rejected" data-id="${s.id}">Keep original</button></div>`:''}${(session.comments[s.id]||[]).map((n,index)=>`<div class="note-entry">${esc(n.text)}<time>${esc(noteByline(n))}${n.origin==='word'?'':` <button class="note-button" data-edit-note="${s.id}" data-index="${index}">Edit</button>`}</time></div>`).join('')}${noteEditor?.id===s.id?`<div class="note-composer"><label for="note-text">Your comment</label><textarea id="note-text" placeholder="Ask a question or explain your thinking…">${esc(noteDrafts[s.id]||'')}</textarea><div class="card-actions"><button class="accept-button" data-save-note="${s.id}">Save comment</button><button class="reject-button" data-cancel-note="${s.id}">Cancel</button></div></div>`:`<button class="note-button" data-note="${s.id}">＋ Comment</button>`}${active&&editable(s)?.editable?`<button class="note-button edit-card" data-edit="${s.id}">Edit wording</button>`:''}${active?`<button class="note-button" style="float:right" data-source="${s.id}">View source</button>`:''}</div>`;}).join('')||`<div class="empty-state"><div class="check-ring">${panel==='notes'?'≡':'✓'}</div><h3>${panel==='notes'?'Room for your reasoning':!changes().length?'A fresh starting point':pending()?'Nothing in this view':'Every change reviewed'}</h3>${panel==='notes'?'Add a comment to a change to record a question or the reason for a decision.':!changes().length?'Select a paragraph, then choose Edit wording.':pending()?'Choose another filter to continue your review.':'You can now export the reviewed source and check its PDF.'}</div>`;
}
function render(){
 if(!review)return;
 $('.app-shell').dataset.view=view;const mobileToggle=$('#mobile-review-toggle');if(mobileToggle){mobileToggle.textContent=view==='redline'&&$('.app-shell').classList.contains('mobile-review-open')?'← Back to document':`Review changes · ${pending()} remaining`;mobileToggle.setAttribute('aria-expanded',String(view==='redline'&&$('.app-shell').classList.contains('mobile-review-open')));}
 $('.version-row').classList.toggle('single-source',session.beforeName===session.afterName);$('#conversion-badge').classList.toggle('hidden',!session.attachments?.length);$('#document-title').textContent=session.title;document.title=`${session.title} · Margin`;$('#matter-name').textContent=session.matter;$('#sample-tag').classList.toggle('hidden',!session.demo);$('#before-name').textContent=session.beforeName;$('#after-name').textContent=session.afterName;
 $('.paper-masthead span').textContent=session.matter.toUpperCase();$('.paper h2').textContent=session.title;$('.paper-subtitle').textContent=view==='reading'?(pending()?'Working wording · Includes unreviewed changes':'Reviewed wording'):changes().length?'A working copy · Changes shown in the text':'Select a paragraph to edit or comment';
 const total=changes().length,done=total-pending();$('#review-progress').innerHTML=`<span>${done} of ${total} reviewed</span><span class="mini-progress"><span style="width:${total?done/total*100:100}%"></span></span>`;
 $('[data-action="undo"]').disabled=!undo.length;
 $$('.view-tabs button').forEach(b=>b.setAttribute('aria-selected',b.dataset.view===view));
 $('#paper').classList.toggle('hidden',view==='source'||view==='pdf');$('#source-panel').classList.toggle('hidden',view!=='source');$('#pdf-panel').classList.toggle('hidden',view!=='pdf');$('#legend').classList.toggle('hidden',view!=='redline');
 $('#stage-label').textContent=view==='redline'?'WORDING & CHANGES':view==='reading'?pending()?'READING · INCLUDES UNREVIEWED CHANGES':'REVIEWED WORDING':view==='source'?'EXACT LATEX SOURCE':'COMPILED DOCUMENT';
 $('#paper-footer-note').textContent='Reading layout · Full typesetting in PDF';
 $('#document-content').innerHTML=documentHtml();renderOutline();renderCards();if(view==='source')renderSource();if(view==='pdf')renderPdf();
}
function choose(id,scroll=false){$('.app-shell').classList.add('mobile-review-open');selected=id;panel=review.segments.find(s=>s.id===id)?.type==='equal'?'notes':'changes';if(!filtered().some(s=>s.id===id))filter='all';render();if(scroll){const el=document.getElementById(id);el?.scrollIntoView({behavior:'smooth',block:'center'});}$(`[data-card="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'nearest'});}
function scheduleCompile(){autoCompileTimer=setTimeout(()=>compilePdf('preview',false,true),900);}
function revealSelection(focus=false){requestAnimationFrame(()=>{document.getElementById(selected)?.scrollIntoView({behavior:'smooth',block:'center'});$(`[data-card="${selected}"]`)?.scrollIntoView({behavior:'smooth',block:'nearest'});if(focus)$('#mobile-actions button')?.focus({preventScroll:true});});}
function decide(id,decision){if(!changes().some(s=>s.id===id))return;undo.push({decisions:clone(session.decisions),selected});session.decisions[id]=decision;session.audit.push({action:decision,id,at:new Date().toISOString(),actor:'Local reviewer'});invalidate();const list=changes(),index=list.findIndex(s=>s.id===id);const next=[...list.slice(index+1),...list.slice(0,index)].find(s=>!session.decisions[s.id]);selected=next?.id||id;persist();render();revealSelection(true);scheduleCompile();toast(decision==='accepted'?'Change accepted · Undo with ⌘Z':'Original wording retained · Undo with ⌘Z');}
function reopen(id){undo.push({decisions:clone(session.decisions),selected});delete session.decisions[id];session.audit.push({action:'reopened',id,at:new Date().toISOString(),actor:'Local reviewer'});selected=id;invalidate();persist();render();scheduleCompile();}
async function doUndo(){if(undoBusy)return;undoBusy=true;try{const last=undo.pop();if(!last){toast('No change to undo in this session.');return;}if(last.session){const remaining=undo;await loadSession(last.session,{archive:false});undo=remaining;selected=last.selected;panel=review.segments.find(s=>s.id===selected)?.type==='equal'?'notes':'changes';if(!filtered().some(s=>s.id===selected))filter='all';render();revealSelection();scheduleCompile();toast(last.kind==='comment'?'Comment change undone':last.kind==='context'?'Review note undone':'Wording edit undone');return;}session.decisions=last.decisions;selected=last.selected;session.audit.push({action:'undo',at:new Date().toISOString(),actor:'Local reviewer'});invalidate();persist();render();scheduleCompile();toast('Last decision undone');}finally{undoBusy=false;}}
function renderSource(){const val=sourceView==='before'?session.before:sourceView==='after'?session.after:material();$('#source-panel').innerHTML=`<div class="source-switch">${[['before','Original'],['after','Proposed'],['reviewed','Reviewed']].map(([key,label])=>`<button class="${sourceView===key?'selected':''}" data-sourceview="${key}">${label}</button>`).join('')}</div><div class="view-note">${sourceView==='reviewed'&&pending()?`${pending()} unreviewed changes are included in this preview. `:''}This is the exact source. The reading view simplifies LaTeX; use the PDF to check typography and references.</div><pre>${esc(val)}</pre>`;}
function renderPdf(){if(pdf){$('#pdf-panel').innerHTML=`<div class="view-note">${pdf.mode==='comparison'?'Your reviewed changes against the original.':pdf.mode==='proposal'?'The full incoming proposal, before your decisions.':pending()?`Working preview · ${pending()} unreviewed changes included.`:'Reviewed version · All changes decided.'} ${pdf.warnings.length?`${pdf.warnings.length} typesetting warning(s).`:''}<button class="text-button" data-action="pdf-details" style="margin-left:12px">Build details</button><button class="text-button" data-action="download-preview" style="margin-left:14px">Download this preview</button></div><div class="pdf-pages">${pdf.images?.length?pdf.images.map((image,i)=>`<figure><figcaption>PAGE ${i+1}${pdf.images.length===30?' · PREVIEW LIMITED TO 30 PAGES':''}</figcaption><img src="data:image/png;base64,${image}" alt="Compiled LaTeX PDF, page ${i+1}" loading="lazy"></figure>`).join(''):`<div class="pdf-empty"><p>${esc(pdf.previewError||'Download this PDF to view it.')}</p></div>`}</div>`;}else{$('#pdf-panel').innerHTML=`<div class="pdf-empty"><h2>The complete typeset document.</h2><p>Compile the current review to check pagination, footnotes, references and the original document layout.${pending()?` This preview includes ${pending()} unreviewed changes.`:''}</p><button class="button primary ${compiling?'spin':''}" data-action="compile" ${compiling?'disabled':''}>${compiling?'Compiling on this Mac…':'Compile PDF'}</button></div>`;}}
async function compilePdf(mode='preview',downloadIt=false,quiet=false){if(compiling){if(!quiet)toast('A PDF is compiling. Please try again shortly.');return;}compiling=true;const current=revision;$('#compile-status').textContent='Compiling…';if(view==='pdf')renderPdf();
 try{const data=await api('pdf',{...session,mode});if(current!==revision){if(!quiet)toast('The review changed during compilation. Checking the current version.');return;}const bytes=Uint8Array.from(atob(data.pdf),c=>c.charCodeAt(0)),blob=new Blob([bytes],{type:'application/pdf'});if(pdf)URL.revokeObjectURL(pdf.url);pdf={...data,url:URL.createObjectURL(blob),blob};$('#compile-status').textContent=['comparison','proposal'].includes(mode)?'Redline PDF compiled':data.warnings.length?'PDF compiled · warnings':'PDF compiled';if(downloadIt)download(blob,`${stem()}_${mode==='comparison'?'reviewed_redline':mode==='proposal'?'incoming_proposal':'reviewed'}.pdf`);else if(!quiet){view='pdf';render();}if(!quiet)toast(data.warnings.length?'PDF compiled. Check the typesetting warnings.':'PDF compiled on this Mac');}
 catch(e){compileError=e.message;$('#compile-status').textContent='PDF needs attention';if(quiet)return;if($('#modal').open)modalError(e);else modal('PDF needs attention','Your review decisions and both source documents are preserved.',`<div class="error-message">${esc(e.message)}</div><p class="hint">Standalone .tex documents are supported. Additional project files and custom local fonts must be compiled in their original project.</p>`,`<button class="button" data-action="close-modal">Return to review</button>`);}
 finally{compiling=false;if(current!==revision){$('#compile-status').textContent='Check PDF';scheduleCompile();}if(view==='pdf')renderPdf();}}
function importModal(mode=openMode){importTicket++;pendingImport=null;openMode=mode;const recent=history().filter(x=>x.workspaceId!==session.workspaceId);modal('Open document','Open a document, compare versions, or pick up where you left off.',`<div class="open-options"><button class="${mode==='single'?'selected':''}" data-open-mode="single">Open a document</button><button class="${mode==='compare'?'selected':''}" data-open-mode="compare">Compare versions</button><button class="${mode==='recent'?'selected':''}" data-open-mode="recent">Recent reviews</button></div>${mode==='recent'?recent.map((x,index)=>`<div class="recent-review"><div><h3>${esc(x.title)}</h3><p>${Object.keys(x.decisions||{}).length} decisions · ${esc(new Date(x.savedAt).toLocaleDateString('en-GB'))}</p></div><button class="button" data-restore="${esc(x.workspaceId)}">Open</button></div>`).join('')||'<p class="hint">Your previous reviews will appear here when you open another document.</p>':`<div class="form-row"><label for="import-title">Document title <span class="hint">(optional)</span></label><input id="import-title" type="text" placeholder="e.g. Settlement agreement"></div>${mode==='single'?`<div class="upload-box">Choose a Word or LaTeX document.<input type="file" id="import-single" accept=".docx,.tex,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" aria-label="Word or LaTeX document"></div><details><summary>Paste text or LaTeX instead</summary><textarea id="paste-single" aria-label="Document text or LaTeX" placeholder="Paste your document text…"></textarea></details>`:`<div class="form-grid"><div><label>Original</label><div class="upload-box">The earlier version<input type="file" id="import-before" accept=".docx,.tex,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" aria-label="Original Word or LaTeX file"></div></div><div><label>Proposed</label><div class="upload-box">The version with changes<input type="file" id="import-after" accept=".docx,.tex,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" aria-label="Proposed Word or LaTeX file"></div></div></div><details><summary>Paste the two versions instead</summary><div class="form-grid"><textarea id="paste-before" aria-label="Original LaTeX source" placeholder="Original LaTeX…"></textarea><textarea id="paste-after" aria-label="Proposed LaTeX source" placeholder="Proposed LaTeX…"></textarea></div></details>`}<p class="hint">Word .docx up to 4 MB · LaTeX up to 300 KB. Conversion stays on this Mac. Your current review is kept in Recent reviews.</p><div class="form-row"><label for="import-session">Or continue a saved Margin review</label><input type="file" id="import-session" accept=".json" aria-label="Saved Margin review"></div>`}`,`<button class="text-button" data-action="load-demo">Try the example</button><button class="button" data-action="close-modal">Cancel</button>${mode!=='recent'?`<button class="button primary" data-action="compare">${mode==='single'?'Open document':'Compare versions'}</button>`:''}`);}
const fromBase64=data=>Uint8Array.from(atob(data),c=>c.charCodeAt(0));
function asBase64(bytes){let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(binary);}
async function readDocument(input,textarea,title){const file=$(input).files[0];if(file&&/\.docx$/i.test(file.name)){if(file.size>4000000)throw Error('Choose a Word document under 4 MB.');const result=await api('word/import',{data:asBase64(new Uint8Array(await file.arrayBuffer())),name:file.name,title});return {...result,name:file.name,word:true};}if(file&&!/\.tex$/i.test(file.name))throw Error('Choose a Word .docx or LaTeX .tex file.');if(file?.size>300000)throw Error('Each LaTeX source must be under 300 KB.');let source;try{source=file?new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await file.arrayBuffer()):$(textarea).value;}catch{throw Error('Please save the LaTeX file as UTF-8 before importing it.');}if(!source.trim())throw Error('Choose a document or paste text.');if(!file&&!source.includes('\\begin{document}')){return {...await api('text/import',{text:source,title}),name:'Pasted text.tex'};}return {before:source,after:source,name:file?.name||'Document.tex',comments:{}};}
function wordReport(value){return {name:value.name,warnings:value.warnings||[],counts:value.counts||{},revisions:value.revisions||[],originalRevisions:value.originalRevisions||[],sourceText:value.sourceText||'',convertedText:value.convertedText||'',unmatchedComments:value.unmatchedComments||[]};}
function conversionMarkup(reports){return reports.map(r=>{const routine=new Set(['restyled_layout','external_hyperlink']);const notices=(r.warnings||[]).filter(w=>!routine.has(w.code));return `<section class="conversion-report"><div class="conversion-filename">${esc(r.name)}</div><div class="conversion-counts">${Object.entries(r.counts||{}).filter(([key,val])=>typeof val==='number'&&val>0&&['paragraphs','footnotes','comments','revisions','insertions','deletions','tables'].includes(key)).map(([key,value])=>`<span><strong>${value}</strong> ${esc(({comments:'comment',revisions:'revision mark',footnotes:'footnote',tables:'table',paragraphs:'paragraph',insertions:'insertion',deletions:'deletion'}[key]||key)+(value===1?'':'s'))}</span>`).join('')}</div>${notices.length?`<div class="conversion-notes"><h3>Details to check</h3><ul>${notices.map(w=>`<li>${esc(typeof w==='string'?w:w.message||JSON.stringify(w))}</li>`).join('')}</ul></div>`:'<p class="hint">No unsupported content was detected.</p>'}${r.sourceText||r.convertedText?`<details><summary>Compare the wording</summary><p class="hint">Proposed wording, including incoming revisions. Check page layout in the PDF.</p><div class="conversion-comparison"><div><h3>From Word</h3><pre>${esc(r.sourceText)}</pre></div><div><h3>Converted document</h3><pre>${esc(r.convertedText)}</pre></div></div></details>`:''}${r.originalRevisions?.length?`<details><summary>Incoming revision record · ${r.originalRevisions.length}</summary>${r.originalRevisions.map(n=>`<div class="note-entry">${esc(n.text||'Paragraph or formatting revision')}<time>${esc(n.kind||n.type||'Revision')} · ${esc(n.author||'Author not supplied')} · ${esc(n.at||n.date||'Date not supplied')}</time></div>`).join('')}</details>`:''}${r.unmatchedComments?.length?`<details open><summary>Comments needing their original context</summary>${r.unmatchedComments.map(n=>`<div class="note-entry">${esc(n.text)}<time>${esc(n.author||'Author not supplied')}</time></div>`).join('')}</details>`:''}</section>`;}).join('');}
function showConversion(opening=false){const reports=opening?pendingImport.conversion.reports:session.conversion?.reports||[];modal(opening?'Your Word document, in Margin':'Conversion record','The original Word file is preserved. Margin applies a consistent legal layout.',conversionMarkup(reports),opening?`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="open-converted">Open converted document</button>`:`<button class="button primary" data-action="close-modal">Back to document</button>`);}
async function importDocuments(){if(importBusy)return;importBusy=true;const ticket=++importTicket;const button=$('#modal [data-action="compare"]');const label=button.textContent;button.disabled=true;button.textContent='Opening…';try{const title=$('#import-title').value;const before=await readDocument(openMode==='single'?'#import-single':'#import-before',openMode==='single'?'#paste-single':'#paste-before',title);const after=openMode==='single'?before:await readDocument('#import-after','#paste-after',title);if(ticket!==importTicket)return;const hasWord=before.word||after.word;
 if(openMode!=='single'&&[before,after].some(x=>x.word&&x.before!==x.after))throw Error('This Word file already contains tracked changes. Open it as one document to review those revisions first, then compare the reviewed versions.');
 const next={title:title||after.title||after.name.replace(/\.(tex|docx)$/i,'')||'Document',matter:'Local document review',before:openMode==='single'?before.before:before.after,after:after.after,beforeName:before.name,afterName:after.name,comments:openMode==='single'?before.comments||{}:{},attachments:[...(before.word?[{...before.attachment,role:openMode==='single'?'source':'before'}]:[]),...(openMode!=='single'&&after.word?[{...after.attachment,role:'after'}]:[])]};
 if(openMode!=='single'&&hasWord){const mapped=await api('word/map-comments',{before:next.before,after:next.after,sources:[{side:'before',source:before.after,comments:before.comments||{}},{side:'after',source:after.after,comments:after.comments||{}}]});next.comments=mapped.comments;}
 if(hasWord){next.conversion={kind:'word',reports:(openMode==='single'?[before]:[before,after]).filter(x=>x.word).map(wordReport),at:new Date().toISOString()};pendingImport=next;showConversion(true);}else{await loadSession(next);$('#modal').close();view='redline';render();toast(changes().length?`${changes().length} changes ready for review`:'Document opened · Use Edit wording to make changes');}
 }catch(e){if(ticket===importTicket)modalError(e);}finally{importBusy=false;if(button.isConnected){button.disabled=false;button.textContent=label;}}}
async function openConverted(){if(!pendingImport)return;const next=pendingImport;await loadSession(next);pendingImport=null;$('#modal').close();view='redline';render();toast(`${changes().length} changes · Original Word file preserved`);}
async function downloadOriginal(index){const file=session.attachments[index],result=await api('word/original',{hash:file.hash});download(new Blob([fromBase64(result.data)],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}),file.name);}
async function portableSession(){const data={format:'margin-review',version:1,...clone(session)};for(const file of data.attachments||[]){const original=await api('word/original',{hash:file.hash});file.data=original.data;}return data;}
async function wordExport(mode){if(wordExportBusy)return;wordExportBusy=true;const current=revision,generation=modalGeneration,button=$(`[data-export="${mode==='tracked'?'word-redline':'word'}"]`);const label=button?.textContent;if(button){button.disabled=true;button.textContent='Preparing…';}try{const result=await api('word/export',{session,mode});if(generation!==modalGeneration||!$('#modal').open)return;if(current!==revision)throw Error('The review changed. Export the current version again.');const prepared={...result,name:`${stem()}_${mode==='tracked'?'reviewed_redline':'reviewed'}.docx`};modal('Your Word document is ready',mode==='tracked'?'Changes are native Word revisions, ready for the next reviewer.':'An editable Word document with your decisions applied.',`<div class="word-export-ready"><span class="file-icon">DOCX</span><div><h3>${mode==='tracked'?'Reviewed redline':'Reviewed document'}</h3><p>${esc(session.title)}</p></div></div><p class="hint">${mode==='tracked'?'New comparison revisions are labelled “Margin”. Incoming revision authors remain in the original Word file and conversion record.':'Review comments with safe anchors are included.'} The document uses Margin’s legal layout.</p>${result.warnings?.some(w=>!['restyled_layout','generated_comparison'].includes(w.code))?`<div class="conversion-notes"><h3>Conversion notes</h3><ul>${result.warnings.filter(w=>!['restyled_layout','generated_comparison'].includes(w.code)).map(w=>`<li>${esc(typeof w==='string'?w:w.message||JSON.stringify(w))}</li>`).join('')}</ul></div>`:''}`,`<button class="button" data-action="close-modal">Back</button><button class="button primary" data-action="download-word">Save Word document</button>`);pendingWordExport=prepared;}catch(e){if(generation===modalGeneration&&$('#modal').open)modalError(e);}finally{wordExportBusy=false;if(button?.isConnected){button.disabled=false;button.textContent=label;}}}
function exportModal(){const blocked=pending()>0;modal('Export document',blocked?`${pending()} changes still need your decision. You can save and continue this review at any time.`:'Your decisions are applied to both the clean document and its redline.',`<div class="export-option"><span class="file-icon">PDF</span><div><h3>Reviewed document</h3><p>Your chosen wording in Word or PDF.</p></div><div class="export-buttons"><button class="button" data-export="word" ${blocked?'disabled':''}>Word</button><button class="button primary" data-export="pdf" ${blocked?'disabled':''}>PDF</button></div></div><div class="export-option"><span class="file-icon">± PDF</span><div><h3>Redline of your review</h3><p>Your reviewed wording compared with the original.</p></div><div class="export-buttons"><button class="button" data-export="word-redline" ${blocked?'disabled':''}>Word</button><button class="button" data-export="comparison" ${blocked?'disabled':''}>PDF</button></div></div><div class="export-option"><span class="file-icon">MARGIN</span><div><h3>Continue this review</h3><p>Keep all wording, decisions and comments together.</p></div><button class="button" data-export="session">Save review</button></div><details><summary>Source files &amp; review record</summary><div class="export-option"><div><h3>Structured review record</h3><p>Exact wording, decisions, questions and source references for other tools. No legal approval is implied.</p></div><button class="button" data-export="record">Save JSON</button></div><div class="export-option"><div><h3>Reviewed LaTeX</h3><p>Exact source with your decisions applied.</p></div><button class="button" data-export="tex" ${blocked?'disabled':''}>Save .tex</button></div><div class="export-option"><div><h3>Full proposal redline</h3><p>Every proposed change, before your decisions.</p></div><button class="button" data-export="proposal">Save proposal</button></div></details>`,`<button class="button" data-action="close-modal">Back to document</button>`);}
async function exportFile(kind){try{if(kind==='word'||kind==='word-redline'){await wordExport(kind==='word-redline'?'tracked':'clean');return;}if(kind==='record'){download(JSON.stringify(buildReviewRecord(session,review),null,2),`${stem()}.margin-record.json`,'application/json');toast('Review record saved');}else if(kind==='session'){download(JSON.stringify(await portableSession(),null,2),`${stem()}.margin.json`,'application/json');toast('Review file saved');}else if(kind==='tex'){const result=await api('export',{...session,mode:'clean'});download(result.source,`${stem()}_reviewed.tex`);toast('Reviewed LaTeX saved');}else{const button=$(`[data-export="${kind}"]`),label=button.textContent;button.disabled=true;button.textContent='Preparing…';await compilePdf(['comparison','proposal'].includes(kind)?kind:'clean',true);button.disabled=false;button.textContent=label;}}catch(e){modalError(e);}}
function noteModal(id,index){$('.app-shell').classList.add('mobile-review-open');if(index!==undefined&&session.comments[id][index].origin==='word')throw Error('Imported comments are preserved. Add a new comment to respond.');selected=id;noteEditor={id,index};if(index!==undefined)noteDrafts[id]=session.comments[id][index].text;panel=review.segments.find(s=>s.id===id)?.type==='equal'?'notes':'changes';if(!filtered().some(s=>s.id===id))filter='all';render();$('#note-text')?.focus();}
function editModal(id){const segment=review.segments.find(s=>s.id===id),editor=editable(segment);if(!editor?.editable)throw Error(editor?.reason||'Choose a prose paragraph.');modal('Edit wording',segment.section,`<label for="edit-text">Wording</label><textarea id="edit-text" class="edit-paragraph">${esc(editor.text)}</textarea><p class="hint">Your wording will be tracked against the original. Formatting stays in place.</p>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-save-edit="${id}">Save wording</button>`);$('#edit-text').focus();}
async function saveEdit(id){const previous=clone(session),oldUndo=undo.slice(),oldSelected=selected;const next=await api('revise',{session,id,text:$('#edit-text').value});if(next.after===session.after){$('#modal').close();return;}await loadSession(next,{archive:false});undo=[...oldUndo,{session:previous,selected:oldSelected}];selected=next.audit.at(-1).id;filter='all';view='redline';render();$('#modal').close();revealSelection();scheduleCompile();toast('Wording saved · Undo with ⌘Z');}
function integrityModal(){modal('Document details','Your original files and converted sources are kept separately.',`<p><button class="text-button" data-action="review-context">For the next reader · Purpose, questions &amp; next step</button></p> ${session.attachments.length?`<div class="original-word-files">${session.attachments.map((f,index)=>`<div class="original-word"><div><strong>${esc(f.name)}</strong><p>Original Word file · ${(f.size/1024).toFixed(0)} KB</p></div><button class="button" data-original-word="${index}">Save original</button></div><div class="hash">SHA-256<br>${esc(f.hash)}</div>`).join('')}<button class="text-button" data-action="conversion-record">View conversion record</button></div>`:''}<label>${session.attachments.length?'Converted original wording':'Original'} · ${esc(session.beforeName)}</label><div class="hash">SHA-256<br>${review.beforeHash}</div><label>${session.authoring?'Working proposal · includes your wording edits':'Proposed · '+esc(session.afterName)}</label><div class="hash">SHA-256<br>${review.afterHash}</div>${session.authoring?'<p class="hint">The incoming proposal is also preserved. Save proposal below retrieves the file before your wording edits.</p>':''}<p class="hint">The reading view simplifies LaTeX. The PDF shows the complete typography, footnotes and references. Source hashes identify file contents; this review is not a signed audit record.</p><p class="hint">${review.issues.before.length||review.issues.after.length?'Basic structure checks flagged: '+esc([...review.issues.before,...review.issues.after].join(' ')):'Basic brace and environment checks passed.'}</p>`,`<button class="text-button" data-action="view-source">View LaTeX source</button><button class="button" data-original="before">Save original</button><button class="button" data-original="after">Save proposal</button><button class="button primary" data-action="close-modal">Done</button>`);}
function navigate(delta){const list=filtered();if(!list.length)return;const index=list.findIndex(s=>s.id===selected);choose(list[(index+delta+list.length)%list.length].id,true);}
async function action(name){switch(name){case'import':importModal();break;case'review-context':contextModal();break;case'save-context':{const next=reviewContext({purpose:$('#context-purpose').value,openQuestions:$('#context-questions').value,nextStep:$('#context-next').value});undo.push({session:clone(session),selected,kind:'context'});session.context=next;revision++;persist();render();$('#modal').close();toast('Review note saved · Undo with ⌘Z');break;}case'export':exportModal();break;case'close-modal':modalGeneration++;pendingWordExport=null;importTicket++;pendingImport=null;$('#modal').close();break;case'open-converted':await openConverted();break;case'conversion-record':showConversion();break;case'download-word':if(pendingWordExport){download(new Blob([fromBase64(pendingWordExport.data)],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}),pendingWordExport.name);toast('Word document saved');}break;case'compare':await importDocuments();break;case'undo':await doUndo();break;case'next':navigate(1);break;case'previous':navigate(-1);break;case'recovery':download(recovery,'Margin_recovery.json','application/json');recovery=null;persist();$('#modal').close();break;case'toggle-mobile-review':if(view!=='redline'){view='redline';$('.app-shell').classList.add('mobile-review-open');}else $('.app-shell').classList.toggle('mobile-review-open');render();break;case'focus':$('.app-shell').classList.toggle('focus-mode');break;case'integrity':integrityModal();break;case'view-source':view='source';$('#modal').close();render();break;case'compile':await compilePdf();break;case'review':view='redline';render();break;case'load-demo':if(recovery)throw Error('Save the recovery copy before opening a new document.');await loadSession(clone(demo));$('#modal').close();view='redline';render();break;case'help':modal('Keyboard shortcuts','Keyboard shortcuts work when you are not typing in a field.',`<table class="shortcuts-table"><tr><td>Next / previous change</td><td><kbd>J</kbd> / <kbd>K</kbd></td></tr><tr><td>Accept selected change</td><td><kbd>A</kbd></td></tr><tr><td>Keep original wording</td><td><kbd>R</kbd></td></tr><tr><td>Add a comment</td><td><kbd>N</kbd></td></tr><tr><td>Undo the last decision</td><td><kbd>⌘</kbd> + <kbd>Z</kbd></td></tr></table><p class="hint">Decisions and notes are saved in this browser. Export a review file for a portable copy. No cloud service or AI model receives your documents.</p>`,`<button class="button primary" data-action="close-modal">Done</button>`);break;case'download-preview':if(pdf)download(pdf.blob,`${stem()}_${pdf.mode==='comparison'?'reviewed_redline':pdf.mode==='proposal'?'incoming_proposal':pdf.pending?'working-preview':'reviewed'}.pdf`);break;case'pdf-details':modal('PDF build','Compiled locally from this exact source.',`<div class="hash">SHA-256<br>${esc(pdf.sourceHash)}</div><div class="hint">${pdf.warnings.length?pdf.warnings.map(esc).join('<br>'):'No typesetting warnings were reported.'}</div>`,`<button class="button primary" data-action="close-modal">Done</button>`);}}
document.addEventListener('click',async e=>{if(undoBusy){e.preventDefault();return;}if(e.target.closest('input,textarea,select')||e.target.closest('.note-composer')&&!e.target.closest('button'))return;const b=e.target.closest('button,[data-select],[data-card]');if(!b)return;try{if(b.dataset.action)await action(b.dataset.action);else if(b.dataset.view){view=b.dataset.view;render();}else if(b.dataset.panel){panel=b.dataset.panel;renderCards();}else if(b.dataset.decide)decide(b.dataset.id,b.dataset.decide);else if(b.dataset.reopen)reopen(b.dataset.reopen);else if(b.dataset.note)noteModal(b.dataset.note);else if(b.dataset.saveNote){const text=$('#note-text').value.trim();if(!text)return;undo.push({session:clone(session),selected,kind:'comment'});const id=b.dataset.saveNote,at=new Date().toISOString();if(noteEditor?.index!==undefined){session.comments[id][noteEditor.index]={...session.comments[id][noteEditor.index],text,editedAt:at};}else{(session.comments[id]??=[]).push({text,at});}delete noteDrafts[id];noteEditor=null;revision++;persist();render();toast('Comment saved · Undo with ⌘Z');}else if(b.dataset.cancelNote){noteEditor=null;renderCards();}else if(b.dataset.editNote){noteModal(b.dataset.editNote,Number(b.dataset.index));}else if(b.dataset.openMode){importModal(b.dataset.openMode);}else if(b.dataset.restore!==undefined){const saved=history().find(x=>x.workspaceId===b.dataset.restore);if(!saved)throw Error('This review is no longer available.');if(saved.workspaceId===session.workspaceId){$('#modal').close();return;}await loadSession(saved);$('#modal').close();view='redline';render();toast('Review restored');}else if(b.dataset.edit){editModal(b.dataset.edit);}else if(b.dataset.saveEdit){await saveEdit(b.dataset.saveEdit);}else if(b.dataset.source){const s=review.segments.find(x=>x.id===b.dataset.source);modal('Exact source for this change',s.section,`<div class="form-grid source-excerpt"><div><label>Original · line ${s.oldLine}</label><pre>${esc(s.before||'(No original text)')}</pre></div><div><label>Proposed · line ${s.newLine}</label><pre>${esc(s.after||'(Text removed)')}</pre></div></div>`,`<button class="button primary" data-action="close-modal">Return to review</button>`);}else if(b.dataset.sourceview){sourceView=b.dataset.sourceview;renderSource();}else if(b.dataset.select)choose(b.dataset.select);else if(b.dataset.card)choose(b.dataset.card,true);else if(b.dataset.jump){view='redline';render();document.getElementById(b.dataset.jump)?.scrollIntoView({behavior:'smooth',block:'start'});}else if(b.dataset.export)await exportFile(b.dataset.export);else if(b.dataset.originalWord!==undefined)await downloadOriginal(Number(b.dataset.originalWord));else if(b.dataset.original)download(b.dataset.original==='after'&&session.authoring?session.authoring.originalAfter:session[b.dataset.original],(b.dataset.original==='before'?session.beforeName:session.afterName).replace(/\.docx$/i,'.tex'));}catch(e){if($('#modal').open)modalError(e);else toast(e.message);}});
document.addEventListener('input',e=>{if(e.target.id==='note-text'&&noteEditor)noteDrafts[noteEditor.id]=e.target.value;});
$('#modal').addEventListener('cancel',()=>{modalGeneration++;importTicket++;pendingImport=null;pendingWordExport=null;});
$('#change-filter').addEventListener('change',e=>{filter=e.target.value;renderCards();});
document.addEventListener('change',async e=>{if(e.target.id==='import-session'&&e.target.files[0]){try{if(e.target.files[0].size>25000000)throw Error('This review file is too large.');const data=JSON.parse(await e.target.files[0].text());if(!['margin-review','folio-review'].includes(data.format)||data.version!==1)throw Error('Choose a Margin review file.');await loadSession(data);$('#modal').close();view='redline';render();toast('Review restored');}catch(err){modalError(err);}}});
$('#save-status').addEventListener('click',()=>{if(reviewStorage.conflicted)storageConflictModal();});
$('#save-status').addEventListener('keydown',e=>{if(reviewStorage.conflicted&&['Enter',' '].includes(e.key)){e.preventDefault();e.stopPropagation();storageConflictModal();}});
window.addEventListener('storage',e=>{if(e.storageArea!==localStorage||e.key!==storeKey&&e.key!==null)return;try{reviewStorage.assertCurrent();}catch(error){if(error.code==='REVIEW_STORAGE_CONFLICT')showStorageConflictStatus();}});
window.addEventListener('beforeunload',e=>{if(reviewStorage.conflicted){e.preventDefault();e.returnValue='';}});

document.addEventListener('keydown',e=>{if(undoBusy){e.preventDefault();return;}if($('#modal').open||e.target.closest('input,textarea,select,[contenteditable]'))return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();doUndo();return;}if(e.metaKey||e.ctrlKey||e.altKey)return;const key=e.key.toLowerCase();if(key==='j'){e.preventDefault();navigate(1);}if(key==='k'){e.preventDefault();navigate(-1);}if(key==='a'&&selected&&!session.decisions[selected])decide(selected,'accepted');if(key==='r'&&selected&&!session.decisions[selected])decide(selected,'rejected');if(key==='n'&&selected)noteModal(selected);if(e.key==='Enter'&&e.target.matches('[data-card],[data-select]'))e.target.click();});

function contextModal(){const c=reviewContext(session.context);modal('For the next reader','A little context can make the next conversation easier.',`<div class="form-row"><label for="context-purpose">What are we trying to settle?</label><textarea id="context-purpose" maxlength="4000" placeholder="The purpose of this review">${esc(c.purpose)}</textarea></div><div class="form-row"><label for="context-questions">What still needs an answer?</label><textarea id="context-questions" maxlength="4000" placeholder="Questions or assumptions to check">${esc(c.openQuestions)}</textarea></div><div class="form-row"><label for="context-next">What should happen next?</label><textarea id="context-next" maxlength="4000" placeholder="The next step and who should be involved">${esc(c.nextStep)}</textarea></div><p class="hint">Optional. Kept with your saved review and structured record. Accepting wording does not record legal approval.</p>`,`<button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-action="save-context">Save note</button>`);}
async function importWordHandoff(){
 const match=location.hash.match(/^#word=([a-f0-9]{48})$/);if(!match)return;
 const ticket=++importTicket;
 modal('Opening from Word','Preparing a separate local snapshot.',`<p class="hint">Your open Word document stays in Word. Review the conversion before continuing here.</p>`,`<button class="button" data-action="close-modal">Cancel</button>`);
 try{
  const snapshot=await api('word/handoff/read',{ticket:match[1]});
  window.history.replaceState(null,'',location.pathname+location.search);
  if(ticket!==importTicket)return;
  const result=await api('word/import',snapshot);
  if(ticket!==importTicket)return;
  pendingImport={title:result.title||snapshot.name.replace(/\.docx$/i,''),matter:'Snapshot from Word',before:result.before,after:result.after,beforeName:snapshot.name,afterName:snapshot.name,comments:result.comments||{},attachments:[{...result.attachment,role:'source'}],conversion:{kind:'word',reports:[wordReport({...result,name:snapshot.name})],at:new Date().toISOString(),origin:'word_addin_snapshot'}};
  showConversion(true);
 }catch(e){if(ticket===importTicket)modalError(e);}
}

async function init(){try{config=await(await fetch('/api/config')).json();let cached,raw;try{raw=reviewStorage.readActive();cached=JSON.parse(raw);}catch{recovery=raw;}try{await loadSession(cached||clone(demo),{archive:false});}catch(e){recovery=raw;await loadSession(clone(demo),{archive:false});}if(recovery){modal('Keep your saved review','The saved review could not be restored. Its original data has been preserved.',`<p class="hint">Save a recovery copy before starting another review. The fictional example is open and will not overwrite your saved data.</p>`,`<button class="button primary" data-action="recovery">Save recovery copy</button>`);}if(!recovery)await importWordHandoff();const context=document.modelContext;if(context?.registerTool){Promise.resolve(context.registerTool({name:'read_margin_review',title:'Read current Margin review',description:'Read exact sources, wording decisions, comments, unresolved questions and limits. No legal approval or authority to act is recorded. Does not change the review.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('This read-only tool expects an empty object.');return buildReviewRecord(session,review);}})).catch(()=>{});}}catch(e){$('#document-content').innerHTML=`<div class="error-message">${esc(e.message)}</div>`;$('#save-status').textContent='Workspace unavailable';}}
init();
